import re
import string

class LongestWord:

    def __init__(self):
        self.word_list = []

    def _clean_sentence(self, sentence):
        sentence = sentence.lower()
        sentence = re.sub('[%s]' % re.escape(string.punctuation), '', sentence)
        return sentence

    def _split_into_words(self, sentence):
        return re.split(' ', sentence)

    def _is_valid_word(self, word):
        return word in self.word_list

    def add_word(self, word):
        self.word_list.append(word)

    def find_longest_word(self, sentence):
        longest_word = ""
        cleaned_sentence = self._clean_sentence(sentence)
        words = self._split_into_words(cleaned_sentence)
        for word in words:
            if self._is_valid_word(word) and len(word) > len(longest_word):
                longest_word = word
        return longest_word
